INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('88cf4511-5b1e-43e3-a075-e24d643a8670', '21feff02-016d-46e2-bb9d-c27495133b1b', '81. óra: Százalékszámítás', '1 egész = 100%, 1% fogalma (századrész), százalék és törtrész kapcsolata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d155f51b-6ed4-4a1a-a74e-dcd2f5b9308e", "text": "Mit jelent a 1% (egy százalék) fogalma?", "type": "multiple-choice", "options": [{"id": "0e9dcd5f-72f7-44b9-bbe9-895dfeda3ec0", "text": "Az egész mennyiség 1/100-ad részét (századrészét)", "isCorrect": true}, {"id": "c3eea1ae-4150-4855-9a1e-76f394152af1", "text": "Az egész 1/10-ed részét", "isCorrect": false}, {"id": "9f7ff23e-c5f3-4a71-a241-4747c8dbe806", "text": "100 egészet", "isCorrect": false}, {"id": "4c2e5010-1ce5-4e15-9ee8-addef207c0c6", "text": "Az egész felét", "isCorrect": false}], "timeLimit": 15}, {"id": "d4754f04-55c4-4a1e-808c-f1d99677e011", "text": "Hány százalék felel meg a teljes egésznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "a5d82281-aa17-41ea-95b3-914d3ee230be", "text": "Hány százalék felel meg a fél (1/2) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "85005f7b-ad92-436a-b340-f1d3e989044d", "text": "Hány százalék felel meg a negyed (1/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "7c8d66c5-e282-42ac-8530-161df42cffa2", "text": "Hány százalék felel meg a háromnegyed (3/4) mennyiségnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "8b40db39-a4eb-4124-b506-2de7dbe477de", "text": "A 10% az egész 1/10-ed részét jelenti.", "type": "true-false", "options": [{"id": "2848267b-097f-4386-95c9-04a628750853", "text": "Igaz", "isCorrect": true}, {"id": "33c5cdba-c1aa-461b-9114-d14b15c2b90d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fb4d1ba5-36f8-4af2-8148-183168c62220", "text": "A 20% az egész 1/5-öd részének felel meg.", "type": "true-false", "options": [{"id": "5f8bbab6-9d45-4d71-9841-2ce774a7d74d", "text": "Igaz", "isCorrect": true}, {"id": "ef31d666-0cbf-4ca4-a670-2955b944083e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('5a8182f4-f800-417d-b647-d47429dd64b7', '21feff02-016d-46e2-bb9d-c27495133b1b', '82. óra: A százalékszámítás gyakorlása', 'Százalékérték kiszámítása következtetéssel (1% kiszámítása) vagy törtrésszel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d471d151-3584-4cda-9300-c39b4cacf475", "text": "Mennyi 500 Ft-nak a 10%-a? (500 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "a659e12e-598f-4644-b74e-f27d68bf9efa", "text": "Mennyi 500 Ft-nak az 1%-a? (500 / 100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "0a7e4ac3-dd90-4a57-bd07-81e3bed0d969", "text": "Mennyi 500 Ft-nak a 20%-a? (500 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "2a5fe902-64c6-4a68-a641-223e38814524", "text": "Mennyi 800 kg-nak az 50%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "abc90f69-15b6-4dcb-9231-9f064f36df97", "text": "A százalékérték kiszámításához az alapmennyiséget megszorozzuk a százaléklábbal és elosztjuk 100-zal.", "type": "true-false", "options": [{"id": "0735de00-3126-4d44-ac22-05240703edf2", "text": "Igaz", "isCorrect": true}, {"id": "846a9c35-09ca-42fc-a42c-d9698b028b2a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "611051fb-d691-428f-9d5c-09306fb2ff00", "text": "Mennyi 200 Ft-nak a 25%-a? (200 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "91055c5c-820b-4dab-bdd1-1a577e8dd105", "text": "Mennyi 1000 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}]'::jsonb, true, NOW()),
('b24b19eb-4fd4-4199-9e3a-3c4c9c2e9ff4', '21feff02-016d-46e2-bb9d-c27495133b1b', '83. óra: Feladatmegoldás', 'Százalékszámítással kapcsolatos hétköznapi szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "2de65310-204f-4076-8c97-8c62a80ee975", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezmény összege? (10000 * 0,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "727d149d-14c4-415d-9993-cf3028b2046a", "text": "Egy 10 000 Ft-os cipő árából 20% kedvezményt adnak. Mennyi a kedvezményes ár? (10000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8000"}, {"id": "4a3cf5ab-37fc-421a-ab25-fdb8531d61c0", "text": "Egy iskolában 400 tanuló van. 55%-uk lány. Hány lány jár az iskolába? (400 * 0,55)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "220"}, {"id": "d30391c3-30b8-4263-81ec-067566ac7584", "text": "Hány fiú jár az iskolába? (400 - 220)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "11817b67-4f09-4413-9297-83fdbd4208e7", "text": "A kedvezményes ár kiszámításához az eredeti árból kivonjuk a kedvezmény értékét.", "type": "true-false", "options": [{"id": "28316ded-42f6-405a-a199-d2873bf2f5b2", "text": "Igaz", "isCorrect": true}, {"id": "e71c8482-5365-40d1-8c66-68f178b2564a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dcc6c7a8-3727-4bb2-a7fd-9a947484ab75", "text": "Ha egy ár 10%-kal nő, az új ár az eredeti ár 110%-a lesz.", "type": "true-false", "options": [{"id": "23a9b026-d36c-4e0e-8e78-1978461e3ef4", "text": "Igaz", "isCorrect": true}, {"id": "8fbad438-b904-4247-b1de-4a1d65a26ed4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "697cf3a6-3b3f-4ab8-9373-820c4b80eeff", "text": "Mennyi 50 000 Ft 5%-os kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}]'::jsonb, true, NOW()),
('dbefb7a7-407a-4ecf-b7d2-4c76d8cb27fa', '21feff02-016d-46e2-bb9d-c27495133b1b', '84. óra: Feladatmegoldás II.', 'Összetettebb százalékszámítási feladatok, árleértékelések, drágulások.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "00d126f6-da1c-46d6-84d8-16fd04321ef7", "text": "Egy 20 000 Ft-os kabát árát 15%-kal felemelték. Hány Ft a drágulás értéke? (20000 * 0,15)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "24fddb85-c353-4454-bec2-2a312047c01f", "text": "Mennyi a kabát új ára a 15%-os drágulás után? (20000 + 3000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "23000"}, {"id": "0e929df9-6b62-4a84-b005-4196ca49800d", "text": "A 30-as létszámú osztályban a tanulók 10%-a hiányzott. Hány tanuló hiányzott?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "18a1e777-89a4-4213-bd49-624726ba85c3", "text": "Hány tanuló volt jelen az osztályban? (30 - 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "e53c2bcf-b5ec-4209-8d52-f70b8224de32", "text": "Ha a 100 Ft-os termék ára 50%-kal csökken, majd a kedvezményes ár 50%-kal nő, az ár visszatér 100 Ft-ra.", "type": "true-false", "options": [{"id": "4b9e44aa-e05a-4697-a296-34fc4dd8c15b", "text": "Igaz", "isCorrect": false}, {"id": "559f7bcc-6644-4c2c-a1ed-aa2e6aa8e58d", "text": "Hamis (50 Ft 50%-os növekedése 75 Ft lesz!)", "isCorrect": true}], "timeLimit": 15}, {"id": "4d78852c-1ee4-4ff3-92cf-59fc1591265d", "text": "Mennyi 400 liter 75%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "9783730b-a87b-4e95-b076-4afb3d99a73c", "text": "A százalékszámítás alapvető ismeret a mindennapi pénzügyi tájékozódáshoz.", "type": "true-false", "options": [{"id": "4c06fbaa-f1fc-4170-a891-26195fec3bd8", "text": "Igaz", "isCorrect": true}, {"id": "51741748-ec56-4752-90d3-d6d30ec0c803", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('794de7f0-a8aa-417f-acd7-5fd2357bd616', '21feff02-016d-46e2-bb9d-c27495133b1b', '85. óra: Projektóra', 'Családi költségvetés készítése megadott keretből, százalékos megoszlások számítása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "2a0e3a26-8f96-4b51-b325-f030e78a90eb", "text": "Ha a család havi jövedelme 400 000 Ft, és 30%-ot költenek lakhatásra, hány Ft a lakhatási költség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "3d58e4e3-909d-4f67-8029-d473b80252ac", "text": "Ha a jövedelem 40%-át élelmiszerre költik, hány Ft megy élelmiszerre? (400000 * 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "dde37e87-0575-4c8e-a946-813486738324", "text": "Hány Ft marad megtakarításra és egyéb kiadásokra? (400000 - 120000 - 160000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120000"}, {"id": "123e4d95-4e3b-4c32-9668-68aaba3fdfa7", "text": "A családi költségvetés készítésekor a kiadások összege nem haladhatja meg a bevételeket.", "type": "true-false", "options": [{"id": "9ab8c7ed-aba6-4637-94f3-d2f3a39efa87", "text": "Igaz", "isCorrect": true}, {"id": "789a7d54-5874-4cd2-b1dd-860a57614470", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aeed9856-346d-4fc0-a1b2-5f45f9f74967", "text": "Hány százalékot tesz ki a megmaradt 120 000 Ft a 400 000 Ft-os jövedelemből?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "24aee0a0-85d5-4924-9f32-29e0c6b4ca2d", "text": "A százalékos megoszlás kördiagramon ábrázolva jól szemlélteti a kiadások arányát.", "type": "true-false", "options": [{"id": "94596851-71ea-4cac-8c56-c27c35143d6f", "text": "Igaz", "isCorrect": true}, {"id": "09772585-0968-4cfa-9a82-ee195d9da9cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "64496754-ff10-42fa-9f21-59cc7695d2d9", "text": "A tudatos pénzügyi tervezés segít elkerülni az eladósodást.", "type": "true-false", "options": [{"id": "ae5c5b21-061e-4f48-bbab-144c99b88a08", "text": "Igaz", "isCorrect": true}, {"id": "c26832ff-2de2-4432-85e6-efd0831effa0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('0130e0cb-c7b6-42da-abcb-98bf00a784cd', '21feff02-016d-46e2-bb9d-c27495133b1b', '86. óra: Nyitott mondatok', 'Lebontogatás (visszafelé gondolkodás) és próbálgatás módszere egyenleteknél.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "e32ae61c-4808-45a0-88e1-b6821f9b59fb", "text": "Mit jelent a lebontogatás (visszafelé gondolkodás) módszere?", "type": "multiple-choice", "options": [{"id": "bceba025-6f42-412d-a5cb-c93bda81c349", "text": "A végeredményből kiindulva az inverz (ellentétes) műveleteket végezzük el visszafelé", "isCorrect": true}, {"id": "7e1cc6a3-8fb8-4317-835b-358f0b321737", "text": "Visszafelé írjuk le a számokat", "isCorrect": false}, {"id": "efc72137-2cd7-443b-9efb-46205ddae5b1", "text": "Tippelünk egy számot és feladjuk", "isCorrect": false}, {"id": "a9bb96d4-b0b0-415a-824d-1afd7c189d7b", "text": "Kivonunk mindent 100-ból", "isCorrect": false}], "timeLimit": 15}, {"id": "2bb9a07d-6e94-46e4-83e6-d28fee79b13d", "text": "Melyik szám teszi igazzá: 2 * x + 5 = 17? (17 - 5 = 12, 12 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ffc590e7-a3a7-4467-82e1-6741e609c51c", "text": "Melyik szám teszi igazzá: (y - 4) : 3 = 5? (5 * 3 = 15, 15 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "19"}, {"id": "e3b5612d-49d3-4046-869f-066960f9183f", "text": "Az ellenőrzés során a kapott értéket behelyettesítjük az eredeti nyitott mondatba.", "type": "true-false", "options": [{"id": "6ec2cdbd-a2e6-4b75-81e1-2aafb55ce8a5", "text": "Igaz", "isCorrect": true}, {"id": "d6d72cbc-cb97-4dba-95e6-6f164acebbb7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a7bc2c1b-3b90-4a16-9417-7c0e4fcd800d", "text": "Melyik szám teszi igazzá: 3 * a - 10 = 20?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "1aeab98c-8b42-4c79-9ec2-b41cd6e8b07e", "text": "A próbálgatásos módszernél rendszerezett táblázatot érdemes vezetni.", "type": "true-false", "options": [{"id": "36d5f064-3e91-439c-bed2-a6362f04768c", "text": "Igaz", "isCorrect": true}, {"id": "b137ce8a-b5ba-4dd7-b15b-307a4b989d86", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8816a400-213a-4be6-b370-fe47787f76c8", "text": "Melyik szám teszi igazzá: x / 4 + 2 = 7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('b1a10aa3-4a14-4bf0-a9bf-0896b010dfa3', '21feff02-016d-46e2-bb9d-c27495133b1b', '87. óra: Feladatmegoldás: Nyitott mondatok', 'Gyakorlás: lebontogatási módszer alkalmazása egyenletek és egyenlőtlenségek megoldásában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bc478140-f0fd-43c8-ac36-09efb849962d", "text": "Melyik szám teszi igazzá: 4 * (x + 2) = 36? (36/4 = 9, 9-2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "3473c6e4-c7a3-495a-a5ad-4d1ad2665ac9", "text": "Melyik szám teszi igazzá: 5 * y - 12 = 38? (50/5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e0dde77d-84a6-4a4b-9f24-1b32f86eabc7", "text": "Ha az alaphalmaz a természetes számok (0, 1, 2, ...), hány megoldása van a 2 * x < 6 egyenlőtlenségnek? (x = 0, 1, 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "be5ea101-8b89-4142-9219-1096905fc8c1", "text": "Az egyenlőtlenségeknek több megoldása is lehet egy megadott alaphalmazon.", "type": "true-false", "options": [{"id": "67a7724c-656c-4d2f-9e11-4003d07b87ef", "text": "Igaz", "isCorrect": true}, {"id": "8188b449-0cf7-46bd-9296-e0f5585bdf5d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "feb3a8cf-05b4-44a9-bed7-a3d62797d5de", "text": "Melyik szám teszi igazzá: (z + 10) / 2 = 15?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "d8255d8a-2e62-4c1f-8a2d-e4946d259cdc", "text": "Ha az egyenletnek nincs megoldása az adott alaphalmazon, az igazsághalmaz az üres halmaz.", "type": "true-false", "options": [{"id": "39790224-dbf1-43c2-93a2-34cfb399a4b2", "text": "Igaz", "isCorrect": true}, {"id": "ba7de18a-01d1-461b-8509-0cec189b828d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ee8bed46-fc5c-49f3-8d76-6396a68bfeb0", "text": "Melyik szám teszi igazzá: 10 * x - 25 = 75?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('effd9381-1179-4020-b431-b626de071d79', '21feff02-016d-46e2-bb9d-c27495133b1b', '88. óra: Gyakorlóóra', 'Nyitott mondatok és műveleti sorrend gyakorlása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "052945ba-a330-4b0b-ba88-cd20c9765de3", "text": "Melyik szám teszi igazzá: 3 * x + 7 = 34?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "93a97d64-6c7b-499f-ba78-49b866dad952", "text": "Melyik szám teszi igazzá: (x - 5) * 6 = 42?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "64358b24-31ea-497f-810a-7ba51130254a", "text": "A lebontogatás lépései során az utolsóként elvégzett művelet inverzével kezdjük a számolást.", "type": "true-false", "options": [{"id": "053e7817-805c-45f8-ae5b-1c1605796896", "text": "Igaz", "isCorrect": true}, {"id": "20405dbd-cc8d-41f0-ac16-750c0f062bcc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d43733f0-03f8-4068-bd9e-0146fe32ec3f", "text": "Mennyi x értéke, ha 50 - 2 * x = 30? (2x = 20)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e2a25a6e-9baa-41d6-8b3b-f1ad73d73903", "text": "Mennyi y értéke, ha y / 3 - 4 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "560b7d6f-ebb5-4094-989f-b360e562ce62", "text": "Az ellenőrzés kihagyása növeli a hibázás kockázatát.", "type": "true-false", "options": [{"id": "bb9673f0-6ccf-4bfa-b5bc-a65fd08a8905", "text": "Igaz", "isCorrect": true}, {"id": "440c7920-c61b-42f3-a280-85d9f9c73635", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dfd728ac-e119-46e2-80a7-af869e029d44", "text": "Melyik szám teszi igazzá: 8 * a + 4 = 68?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()),
('52c1d23f-0a32-4ccc-ab97-ba9d7073aa78', '21feff02-016d-46e2-bb9d-c27495133b1b', '89. óra: Szöveges feladatok', 'Szöveges feladatok megoldása nyitott mondatok felírásával, ábrakészítéssel.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "87f62d63-7d04-4394-a0e4-ff9cecfd8be8", "text": "Gondoltam egy számot, megszóroztam 3-mal, hozzáadtam 12-őt és 45-öt kaptam. Mi volt a szám? (3x + 12 = 45 -> 3x = 33)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "8bfebd6d-868a-4386-bee7-5fb9c61eed00", "text": "Gondoltam egy számot, kivontam belőle 8-at, megszoroztam 4-gyel és 40-et kaptam. Mi volt a szám? ((x-8)*4 = 40 -> x-8 = 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "9c1b76d2-8c09-488a-9d93-ec82b30f244f", "text": "Katinak 3-szor annyi matricája van, mint Petinek. Összesen 48 matricájuk van. Hány matricája van Petinek? (x + 3x = 48 -> 4x = 48)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "8a849607-d864-4cac-bfe2-bb17b9efbb9e", "text": "Hány matricája van Katinak? (3 * 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "b973af83-600e-40b9-b5c2-7c9d421f815b", "text": "A szöveges feladatok megoldásának lépései: Értelmezés -> Adatok/Ismeretlen -> Nyitott mondat -> Számolás -> Ellenőrzés -> Válaszmondat.", "type": "true-false", "options": [{"id": "24f3b0be-0e1b-4f3e-b249-f20a9d84d6d9", "text": "Igaz", "isCorrect": true}, {"id": "5528306c-ed1d-4068-bf30-e3bc332fb582", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fb73eb90-6b08-4cfd-803c-ebac945ef047", "text": "Ha a feladatban a ''kétszer annyi'' kifejezés szerepel, 2-vel való szorzásra gondolunk.", "type": "true-false", "options": [{"id": "ad5caa0f-ca64-4ba0-ad61-d66a051e40fc", "text": "Igaz", "isCorrect": true}, {"id": "b98303ff-f6b1-4ac8-b60f-f06a994b5874", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "77e5ddfa-d955-46d9-8157-fdf8d043ffb5", "text": "Gondoltam egy számot, elosztottam 5-tel, hozzáadtam 7-et és 12-őt kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW()),
('118bb9a3-b53a-4db1-84a3-fcf40ce8f84c', '21feff02-016d-46e2-bb9d-c27495133b1b', '90. óra: Gyakorlóóra', 'Matematikai szövegezésű feladatok gyakorlása, ábrakészítés, összefüggések.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b25d5e21-52f3-4e1b-8737-21aa2ea12e48", "text": "Apa 4 évvel idősebb, mint Anya. Életkoruk összege 76 év. Hány éves Anya? (2x + 4 = 76 -> 2x = 72)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "b2da453c-1a76-4eda-b95f-291ae70802be", "text": "Hány éves Apa? (36 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "93f7b1d2-d0e1-4c81-89a2-0bc9220f85e8", "text": "Egy téglalap kerülete 40 cm. Hosszabbik oldala 4 cm-rel hosszabb a rövidebbnél. Hány cm a rövidebb oldal? (2*(x + x+4) = 40 -> 4x + 8 = 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "03c9eb12-f19b-4f1a-9aee-8e9999a1a6d6", "text": "Hány cm a hosszabbik oldal? (8 + 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "a27b5eec-3f79-4110-a309-3765684559a3", "text": "A szakaszos ábrázolás nagymértékben segít a szöveges feladatok összefüggéseinek megértésében.", "type": "true-false", "options": [{"id": "8427ee56-e2a8-4e92-b0c6-c3cfaf15b28b", "text": "Igaz", "isCorrect": true}, {"id": "24745696-54bb-47a6-9882-556bc65f0e81", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03b4c751-0e34-4e8e-8096-19fae653302d", "text": "Három egymást követő egész szám összege 45. Mi a legkisebb szám? (x + x+1 + x+2 = 45 -> 3x + 3 = 45)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "033c2531-0691-4caa-a9b5-fff8aa91a892", "text": "A válaszmondat felírása kötelező a szöveges feladat végén.", "type": "true-false", "options": [{"id": "0347d407-5cb4-4a39-b7c3-73e0e69152e1", "text": "Igaz", "isCorrect": true}, {"id": "848ce9cf-7a4e-45e6-92dd-ab5e810eab4d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;